use std::collections::{HashMap,HashSet};struct Twitter{tm:i64,tw:HashMap<i32,Vec<(i64,i32)>>,fo:HashMap<i32,HashSet<i32>>}impl Twitter{fn new()->Self{Self{tm:0,tw:HashMap::new(),fo:HashMap::new()}}fn post_tweet(&mut self,u:i32,id:i32){self.tw.entry(u).or_default().push((self.tm,id));self.tm+=1;}fn get_news_feed(&self,u:i32)->Vec<i32>{let mut a=self.tw.get(&u).cloned().unwrap_or_default();if let Some(s)=self.fo.get(&u){for v in s{if let Some(t)=self.tw.get(v){a.extend_from_slice(t)}}}a.sort_by(|x,y|y.0.cmp(&x.0));a.into_iter().take(10).map(|x|x.1).collect()}fn follow(&mut self,a:i32,b:i32){if a!=b{self.fo.entry(a).or_default().insert(b);}}fn unfollow(&mut self,a:i32,b:i32){if let Some(s)=self.fo.get_mut(&a){s.remove(&b);}}}
